async function main() {
  console.log("Seeding…");

  // ── Tracks + playlist ────────────────────────────────────────────────────
  const album = "Gentle Hours · Vol. 1";
  const playlist = await db.playlist.upsert({
    where: { name: album },
    update: {},
    create: { name: album, description: "Six original instrumentals for prayer and rest." },
  });

  let order = await db.track.count();
  for (const t of TRACKS) {
    const existing = await db.track.findFirst({ where: { audioUrl: t.audioUrl } });
    if (!existing) {
      const created = await db.track.create({
        data: { ...t, trackOrder: order, published: true },
      });
      await db.playlistItem.create({
        data: { playlistId: playlist.id, trackId: created.id, position: order },
      });
      order += 1;
      console.log(`  + track ${created.title}`);
    }
  }

  // ── Sample posts ─────────────────────────────────────────────────────────
  const seedSession = await db.anonSession.upsert({
    where: { id: "seed-anonymous-friends" },
    update: {},
    create: { id: "seed-anonymous-friends", displayName: "Friends of this community" },
  });

  for (const p of SAMPLE_POSTS) {
    const existing = await db.post.findFirst({ where: { title: p.title } });
    if (existing) continue;
    const { comments, ...postFields } = p;
    const post = await db.post.create({
      data: {
        ...(postFields as { category: string; title: string; body: string; sameSituation: number; encouraged: number }),
        sessionId: seedSession.id,
      },
    });
    for (const body of comments) {
      await db.comment.create({ data: { postId: post.id, sessionId: seedSession.id, body } });
    }
    console.log(`  + post "${post.title}"`);
  }

  // Daily content: nothing to seed — the daily rotation is pure code over
  // curated Scripture (getDailyContent()). No table, no AI, no cron.

  console.log("Seed complete.");
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => db.$disconnect());
